xql_query:
// ============================================================
// Rule: FTG_High CPU Usage
// Vendor: Fortigate
// Objective:
// Detect activity associated with FTG_High CPU Usage.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1498 - Network Denial of Service

// Fonte de dados: logs brutos do Fortinet FortiGate
dataset = fortinet_fortigate_raw  

// Filtra apenas mensagens que contenham a palavra "cpu"
| filter msg contains "cpu"  

// Converte o valor de utilização de CPU (FTNTFGTcpu) para inteiro
| alter cpu = to_integer(FTNTFGTcpu)  

// Calcula a média de uso de CPU por dispositivo reportado
| comp avg(cpu) as cpu by _reporting_device_name  

// Mantém apenas os casos onde a média de CPU ultrapassa 90%
| filter cpu > 90
